INSERT INTO `columns` (`id`,`title`,`category`,`excerpt`,`body`,`thumbnail`,`status`,`date`,`file`,`builtin`) VALUES (1,'좋은 디자인은 무엇이 다를까?','디자인 일반','좋은 디자인은 무엇이 다를까? — 카탈로그·브로슈어·로고까지, 제작 전에 알아두면 좋은 기준을 퍼스트디자인 인천지사가 정리했습니다.','<h2 id="sec-1">보기 좋은 것과 잘 전달되는 것은 다릅니다</h2><p>디자인 시안을 받아보면 대부분 "예쁘다"는 기준으로 판단하게 됩니다. 하지만 카탈로그, 브로슈어, 리플렛 같은 홍보물의 목적은 감상이 아니라 <strong>전달</strong>입니다. 받아본 사람이 3초 안에 무엇을 하는 회사인지, 왜 연락해야 하는지를 이해하지 못하면 아무리 아름다워도 실패한 디자인입니다.</p><p>좋은 디자인은 화려한 장식이 아니라 정보의 순서를 설계하는 일에서 시작합니다. 무엇을 가장 크게 보여줄지, 무엇을 과감히 뺄지를 결정하는 것이 디자이너의 첫 번째 일입니다.</p><h2 id="sec-2">좋은 디자인의 3가지 조건</h2><p>12년간 3,200건의 프로젝트를 진행하며 확인한, 성과로 이어지는 디자인의 공통점은 세 가지입니다.</p><ul><li><strong>목적이 분명합니다</strong> — 전시회 배포용인지, 관공서 제출용인지, 매장 비치용인지에 따라 판형·분량·톤이 전부 달라집니다.</li><li><strong>타깃이 좁습니다</strong> — "모두에게"는 "아무에게도"와 같습니다. 읽을 사람을 한 명으로 좁힐수록 카피와 이미지가 선명해집니다.</li><li><strong>위계가 살아 있습니다</strong> — 제목, 소제목, 본문, 캡션이 한눈에 구분되면 읽지 않아도 훑는 것만으로 내용이 들어옵니다.</li></ul><h2 id="sec-3">나쁜 디자인이 더 비싼 이유</h2><p>저렴하게 제작한 홍보물이 실제로는 더 비싸지는 경우가 많습니다. 전달이 안 되면 배포한 만큼 기회비용이 사라지고, 결국 다시 만들게 되기 때문입니다. 인쇄물은 한 번 찍으면 수정할 수 없습니다.</p><blockquote><p>디자인 비용은 제작비가 아니라, 배포될 모든 접점의 첫인상에 대한 투자입니다.</p></blockquote><h2 id="sec-4">의뢰 전에 이것만 정리해 보세요</h2><p>디자인 회사에 의뢰하기 전, 아래 세 가지만 정리되어 있어도 결과물의 방향이 크게 달라집니다.</p><ul><li>이 홍보물을 받는 사람은 누구인가</li><li>받은 사람이 해줬으면 하는 행동 한 가지</li><li>참고하고 싶은 레퍼런스 2~3개</li></ul><p>정리가 어려우시면 그대로 오셔도 됩니다. 퍼스트디자인 인천지사는 기획 단계부터 함께 정리해 드립니다.</p>','theme/assets/first/og/og-column-design.jpg','published','2026-07-20','column-design.html',1);
INSERT INTO `columns` (`id`,`title`,`category`,`excerpt`,`body`,`thumbnail`,`status`,`date`,`file`,`builtin`) VALUES (2,'카탈로그 제작 전 체크리스트 5가지','인쇄·홍보물','카탈로그 제작 전 체크리스트 5가지 — 원고·사진·일정 등 시작 전에 준비할 것들을 퍼스트디자인 인천지사가 정리했습니다.','<h2 id="sec-1">① 원고 — 다 넣으려 하지 말고 골라내세요</h2><p>카탈로그 제작에서 가장 오래 걸리는 단계는 디자인이 아니라 원고 정리입니다. 회사의 모든 것을 담으려 하면 아무것도 기억에 남지 않습니다. 페이지당 하나의 메시지를 원칙으로, 꼭 들어가야 할 내용부터 우선순위를 매겨보세요.</p><h2 id="sec-2">② 사진 — 해상도가 완성도의 절반입니다</h2><p>모니터에서 선명해 보이는 웹용 이미지(72dpi)는 인쇄하면 흐릿하게 나옵니다. 인쇄용은 <strong>300dpi 이상</strong>의 원본이 필요합니다. 제품·시설 사진의 원본 파일을 미리 모아두시고, 상태가 좋지 않다면 재촬영을 계획에 넣는 것이 좋습니다.</p><blockquote><p>퍼스트디자인은 자체 스튜디오에서 제품·시설 촬영까지 함께 진행할 수 있습니다.</p></blockquote><h2 id="sec-3">③ 사양 — 판형·페이지 수·후가공을 먼저</h2><p>같은 내용이라도 A4 무선제본과 A5 중철제본은 인상도 비용도 완전히 다릅니다. 배포 방식(우편, 대면 전달, 행사장 비치)을 기준으로 판형을 정하고, 페이지 수는 표지 포함 4의 배수로 계획하세요. 무광 코팅, 에폭시, 박 등 후가공은 견적에 미리 반영해야 일정이 어긋나지 않습니다.</p><h2 id="sec-4">④ 일정 — 인쇄 1주일을 계산에 넣으세요</h2><p>평균적인 제작 기간은 디자인 2주 + 인쇄·가공 1주, 총 3주 전후입니다. 행사나 전시회에 맞춰야 한다면 예비일까지 더해 최소 4주 전에는 시작하는 것이 안전합니다. 급한 일정은 가능 여부를 먼저 확인해 주세요.</p><h2 id="sec-5">⑤ 배포 — 어디서 쓰일지가 디자인을 결정합니다</h2><p>바이어 미팅용이라면 회사 신뢰도를 보여주는 구성으로, 전시회 배포용이라면 한 손에 들어오는 판형과 강한 표지로, 관공서 제출용이라면 규정과 가독성 중심으로 — 같은 카탈로그도 쓰임에 따라 설계가 달라집니다. 문의하실 때 배포처를 알려주시면 가장 정확한 제안을 드릴 수 있습니다.</p>','theme/assets/first/og/og-column-catalog.jpg','published','2026-07-18','column-catalog.html',1);
INSERT INTO `columns` (`id`,`title`,`category`,`excerpt`,`body`,`thumbnail`,`status`,`date`,`file`,`builtin`) VALUES (3,'로고 리뉴얼, 언제 해야 할까?','브랜딩·로고','로고 리뉴얼, 언제 해야 할까? — 브랜드가 보내는 신호와 리뉴얼 타이밍을 퍼스트디자인 인천지사가 정리했습니다.','<h2 id="sec-1">로고 리뉴얼이 필요하다는 4가지 신호</h2><ul><li>명함·홈페이지·간판마다 로고 색과 모양이 조금씩 다르다</li><li>작게 줄이면(앱 아이콘, 도장 등) 뭉개져서 알아볼 수 없다</li><li>사업 영역이 바뀌어 로고가 지금의 회사를 설명하지 못한다</li><li>10년 전 유행하던 그라디언트·입체 효과가 그대로 남아 있다</li></ul><p>두 개 이상 해당된다면 리뉴얼을 검토할 시점입니다.</p><h2 id="sec-2">전면 리뉴얼과 리프레시는 다릅니다</h2><p>모든 리뉴얼이 로고를 완전히 새로 만드는 것은 아닙니다. 인지도가 쌓인 로고라면 형태는 유지하고 컬러·서체·비례만 정돈하는 <strong>리프레시</strong>가 더 효과적일 수 있습니다. 반대로 브랜드 방향 자체가 바뀌었다면 <strong>전면 리뉴얼</strong>이 맞습니다. 어느 쪽인지 판단이 어려우면 현재 로고의 문제를 먼저 진단해 보세요.</p><h2 id="sec-3">리뉴얼은 이렇게 진행됩니다</h2><p>퍼스트디자인의 로고 리뉴얼은 업종·경쟁사·타깃 분석으로 컨셉을 도출하고, 심볼·워드마크·시그니처 조합을 설계한 뒤, 컬러 시스템과 서체 가이드까지 정리해 전달하는 순서로 진행됩니다. 명함·간판·패키지 적용 시안을 함께 드리기 때문에 리뉴얼 후 바로 실무에 적용할 수 있습니다.</p><h2 id="sec-4">리뉴얼할 때 꼭 챙길 것</h2><ul><li><strong>원본 파일(AI)</strong>을 반드시 받아두세요 — 이후 모든 제작물의 기준이 됩니다.</li><li>기존 인쇄물·간판의 교체 일정과 비용도 함께 계획하세요.</li><li>바뀐 로고의 사용 규정(최소 크기, 여백, 금지 사례)을 문서로 남기세요.</li></ul><p>퍼스트디자인은 작업 완료 후 원본 파일을 무상으로 제공합니다.</p>','theme/assets/first/og/og-column-logo.jpg','published','2026-07-15','column-logo.html',1);
INSERT INTO `columns` (`id`,`title`,`category`,`excerpt`,`body`,`thumbnail`,`status`,`date`,`file`,`builtin`) VALUES (4,'인쇄 사고를 막는 원고 준비법','인쇄·홍보물','인쇄 사고를 막는 원고 준비법 — 재인쇄 없는 마감을 위한 데이터 체크포인트를 퍼스트디자인 인천지사가 정리했습니다.','<h2 id="sec-1">가장 흔한 인쇄 사고 3가지</h2><p>인쇄는 한 번 찍으면 되돌릴 수 없습니다. 실제로 가장 자주 일어나는 사고는 화려한 실수가 아니라 사소한 누락입니다.</p><ul><li>전화번호·주소 오타 (가장 많고, 가장 치명적입니다)</li><li>모니터 색과 인쇄 색의 차이</li><li>재단선에 잘려나간 글자</li></ul><h2 id="sec-2">텍스트 — 인쇄 전 원고는 \'최종본\'이어야 합니다</h2><p>디자인이 끝난 뒤의 문구 수정은 오탈자를 만드는 가장 큰 원인입니다. 원고는 디자인 시작 전에 확정하고, 시안 검수 때는 디자인이 아니라 <strong>전화번호, 주소, 홈페이지, 이메일, 담당자명</strong>을 소리 내어 읽으며 확인하세요. 숫자는 두 사람이 교차 확인하는 것이 안전합니다.</p><h2 id="sec-3">이미지 — RGB와 CMYK는 다른 세계입니다</h2><p>모니터는 빛(RGB)으로, 인쇄는 잉크(CMYK)로 색을 만듭니다. 형광톤의 밝은 파랑·초록은 인쇄하면 한 톤 가라앉습니다. 중요한 브랜드 컬러가 있다면 시안 단계에서 인쇄 교정지로 확인하는 것이 확실합니다. 이미지 해상도는 300dpi, 로고는 벡터(AI) 원본을 사용하세요.</p><h2 id="sec-4">여백 — 재단선 3mm의 법칙</h2><p>인쇄물은 큰 종이에 인쇄한 뒤 칼로 잘라 만들기 때문에 1~2mm의 재단 오차가 늘 존재합니다. 배경은 사방 3mm 더 크게(블리드), 글자와 로고는 가장자리에서 최소 5mm 안쪽에 배치해야 잘림 사고를 막을 수 있습니다.</p><blockquote><p>퍼스트디자인은 인쇄 데이터 검수를 자체 인쇄소와 이중으로 진행합니다.</p></blockquote><h2 id="sec-5">최종 검수 체크리스트</h2><ul><li>연락처·주소·URL 오탈자 확인 (소리 내어 읽기)</li><li>이미지 300dpi · CMYK 변환 확인</li><li>재단 여백 3mm · 안전 여백 5mm 확인</li><li>페이지 순서와 쪽수 확인</li><li>최종 PDF를 처음 보는 사람에게 한 번 더 보여주기</li></ul>','theme/assets/first/og/og-column-print.jpg','published','2026-07-12','column-print.html',1);
