INSERT INTO `content_overrides` (`page`,`orig`,`new`) VALUES ('index','본사 12년 제작 노하우를<br>인천에서 그대로 만나보세요','12년 제작 노하우를<br>인천에서 만나보세요');
INSERT INTO `content_overrides` (`page`,`orig`,`new`) VALUES ('about','\n                                    우리는 파일과 전화로만 일하지 않습니다. 필요한 날 바로 만나 원고를 함께 정리하고, 시안 방향을 그 자리에서 맞춥니다. 본사 12년의 제작 시스템 그대로 — 초안을 먼저 확인하고 진행하기 때문에 방향이 틀어질 일이 없습니다.\n                                ','\n                                    우리는 파일과 전화로만 일하지 않습니다.<br>필요한 날 바로 만나 원고를 함께 정리하고, 시안 방향을 그 자리에서 맞춥니다.<br>12년의 제작 시스템 그대로 초안을 먼저 확인하고 진행하기 때문에<br>방향이 틀어질 일이 없습니다.\n                                ');
INSERT INTO `content_overrides` (`page`,`orig`,`new`) VALUES ('about','아트디렉터, 프로젝트 매니저, 편집·브랜딩 디자이너, 촬영 작가 — 전문가 35명+가 프로젝트별 전담팀을 꾸려 <span class="gra_01">처음부터 끝까지 한 팀이 책임집니다</span>.','아트디렉터, 프로젝트 매니저, 편집·브랜딩 디자이너, 촬영 작가 등<br>전문가 35명+이 프로젝트별 전담팀을 꾸려 <span class="gra_01">처음부터 끝까지 한 팀이 책임집니다</span>.');
INSERT INTO `content_overrides` (`page`,`orig`,`new`) VALUES ('about','문제 발생시 유연하게 대응하고 해결책을 찾아내서 클라이언트들의 프로젝트 품질을 높이는 세심한 조각가들','문제 발생시 유연하게 대응하고 해결책을 찾아내서<br>클라이언트들의 프로젝트 품질을 높이는 세심한 조각가들');
INSERT INTO `content_overrides` (`page`,`orig`,`new`) VALUES ('about','만드는 데서 멈추지 않고 알려지는 것까지 챙기는, 촬영부터 채널 운영까지 실행 속도가 다른 마케터들','만드는 데서 멈추지 않고 알려지는 것까지 챙기는,<br>촬영부터 채널 운영까지 실행 속도가 다른 마케터들');
INSERT INTO `content_overrides` (`page`,`orig`,`new`) VALUES ('about','\n                                인천·부천·시흥 서부수도권 <br>\n                                <span class="gra_01">당일 대면 미팅</span>과 <br>\n                                본사 12년의 <span class="gra_01">검증 프로세스</span>\n                            ','\n                                인천·부천·시흥 서부수도권 <br><span class="gra_01">대면 미팅</span>과 12년의 <span class="gra_01">검증 프로세스</span>\n                            ');
INSERT INTO `content_overrides` (`page`,`orig`,`new`) VALUES ('about','기업과 브랜드, 그리고 고객을 이어주는 카탈로그부터 로고까지, 브랜드의 얼굴을 만드는 디자인','기업과 브랜드, 그리고 고객을 이어주는 카탈로그부터 로고까지,<br>브랜드의 얼굴을 만드는 디자인');
INSERT INTO `content_overrides` (`page`,`orig`,`new`) VALUES ('about','\n                                    자체 인쇄소에서 인쇄부터 후가공, 검수,\n                                    납품까지 끝까지 책임지는 팀\n                                ','\n                                    자체 인쇄소에서 인쇄부터<br>후가공, 검수,\n                                    납품까지 끝까지 책임지는 팀\n                                ');
INSERT INTO `content_overrides` (`page`,`orig`,`new`) VALUES ('about','\n                                    촬영·콘텐츠부터 채널 운영까지, 만든 결과물을 성과로 알리는 팀\n                                ','\n                                    촬영·콘텐츠부터 채널 운영까지,<br>만든 결과물을 성과로 알리는 팀\n                                ');
