INSERT INTO `content_overrides` (`page`,`orig`,`new`) VALUES ('catalog','카탈로그 제작을 준비할 때는 목적과 타깃을 먼저 정하고, 그에 맞는 페이지 구성과 분량을 잡는 것이 중요합니다. 원고와 제품 사진이 준비되지 않아도 괜찮습니다 — 원고 정리와 제품 촬영까지 한 팀에서 해결됩니다. 인쇄 단계에서는 용지·코팅·제본 방식에 따라 완성도가 크게 달라지므로, 대면 미팅에서 실물 샘플을 보고 결정하실 수 있습니다.','카탈로그 제작을 준비할 때는 목적과 타깃을 먼저 정하고, 그에 맞는 페이지 구성과 분량을 잡는 것이 중요합니다. 원고와 제품 사진이 준비되지 않아도 괜찮습니다. 원고 정리와 제품 촬영까지 한 팀에서 해결됩니다. 인쇄 단계에서는 용지·코팅·제본 방식에 따라 완성도가 크게 달라지므로, 대면 미팅에서 실물 샘플을 보고 결정하실 수 있습니다.');
