INSERT INTO `content_overrides` (`page`,`orig`,`new`) VALUES ('catalog','제품 라인업과 스펙을 한눈에 비교할 수 있게 정리합니다. 사양표·이미지·설명의 위계를 잡아 영업 현장에서 바로 쓰이는 카탈로그를 만듭니다.','제품 라인업과 스펙을 한눈에 비교할 수 있게 정리합니다.<br>사양표·이미지·설명의 위계를 잡아 영업 현장에서 바로 쓰이는 카탈로그를 만듭니다.');
INSERT INTO `content_overrides` (`page`,`orig`,`new`) VALUES ('catalog','제품 정보에 브랜드 스토리를 더해 회사의 격까지 전달합니다. 기업 소개와 제품 소개가 자연스럽게 이어지도록 구성합니다.','제품 정보에 브랜드 스토리를 더해 회사의 격까지 전달합니다.<br>기업 소개와 제품 소개가 자연스럽게 이어지도록 구성합니다.');
INSERT INTO `content_overrides` (`page`,`orig`,`new`) VALUES ('catalog','해외 전시회와 수출 상담을 위한 영문·다국어 카탈로그를 제작합니다. 언어별 글자 길이에 맞춰 레이아웃을 다시 잡습니다.','해외 전시회와 수출 상담을 위한 영문·다국어 카탈로그를 제작합니다.<br>언어별 글자 길이에 맞춰 레이아웃을 다시 잡습니다.');
