INSERT INTO `content_overrides` (`page`,`orig`,`new`) VALUES ('leaflet','가장 널리 쓰이는 접지 형태입니다. 펼치는 순서에 맞춰 정보를 배치해 어느 면을 먼저 보더라도 메시지가 전달되게 만듭니다.','가장 널리 쓰이는 접지 형태입니다.<br>펼치는 순서에 맞춰 정보를 배치해 어느 면을 먼저 보더라도 메시지가 전달되게 만듭니다.');
INSERT INTO `content_overrides` (`page`,`orig`,`new`) VALUES ('leaflet','제품 라인업이나 단계별 안내처럼 펼쳤을 때 임팩트가 필요한 내용에 적합합니다. 접는 방식부터 함께 설계합니다.','제품 라인업이나 단계별 안내처럼 펼쳤을 때 임팩트가 필요한 내용에 적합합니다.<br>접는 방식부터 함께 설계합니다.');
INSERT INTO `content_overrides` (`page`,`orig`,`new`) VALUES ('leaflet','배포 환경까지 고려해 설계합니다. 거치대 비치, 현장 배포, 우편 발송 등 쓰임에 맞춰 판형과 재질을 정합니다.','배포 환경까지 고려해 설계합니다.<br>거치대 비치, 현장 배포, 우편 발송 등 쓰임에 맞춰 판형과 재질을 정합니다.');
