INSERT INTO `content_overrides` (`page`,`orig`,`new`) VALUES ('pamphlet','8면 이내 분량이라면 접지형이 경제적입니다. 제본 없이도 정보를 구조적으로 정리할 수 있어 현장 배포에 유리합니다.','8면 이내 분량이라면 접지형이 경제적입니다.<br>제본 없이도 정보를 구조적으로 정리할 수 있어 현장 배포에 유리합니다.');
INSERT INTO `content_overrides` (`page`,`orig`,`new`) VALUES ('pamphlet','8페이지 이상 분량은 중철 제본으로 책자 형태를 만듭니다. 행사 안내서, 기관 소개서에 적합합니다.','8페이지 이상 분량은 중철 제본으로 책자 형태를 만듭니다<br>행사 안내서, 기관 소개서에 적합합니다.');
