INSERT INTO `content_overrides` (`page`,`orig`,`new`) VALUES ('brochure','회사의 첫인상을 만드는 자료입니다. 연혁을 나열하는 대신 읽는 사람이 궁금해할 순서로 재구성합니다.','회사의 첫인상을 만드는 자료입니다.<br>연혁을 나열하는 대신 읽는 사람이 궁금해할 순서로 재구성합니다.');
