INSERT INTO `content_overrides` (`page`,`orig`,`new`) VALUES ('svc-studio','브랜드·제품 홍보 영상 기획·촬영·편집 — SNS 숏폼부터 회사소개 영상까지.','브랜드·제품 홍보 영상 기획·촬영·편집<br>SNS 숏폼부터 회사소개 영상까지.');
INSERT INTO `content_overrides` (`page`,`orig`,`new`) VALUES ('svc-mkt','단순한 글쓰기가 아닙니다. 브랜드의 방향성과 톤앤매너를 담아, 홈페이지를 대신할 수 있는 공식 블로그를 전반적으로 운영·관리합니다. 인천 상권·업종 키워드를 분석해 인지도를 높이는 저비용 고효율의 운영대행 서비스입니다.','단순한 글쓰기가 아닙니다. 브랜드의 방향성과 톤앤매너를 담아,<br>홈페이지를 대신할 수 있는 공식 블로그를 전반적으로 운영·관리합니다.<br>인천 상권·업종 키워드를 분석해 인지도를 높이는 저비용 고효율의 운영대행 서비스입니다.');
INSERT INTO `content_overrides` (`page`,`orig`,`new`) VALUES ('svc-mkt','비주얼 중심의 인스타그램은 브랜드 아이덴티티를 시각적으로 전달하고, 브랜드 가치를 효과적으로 확장하는 데 최적의 채널입니다. 인천 매장·브랜드의 감도·분위기·메시지를 피드 하나하나에 담아 운영합니다.','비주얼 중심의 인스타그램은 브랜드 아이덴티티를 시각적으로 전달하고,<br>브랜드 가치를 효과적으로 확장하는 데 최적의 채널입니다.<br>인천 매장·브랜드의 감도·분위기·메시지를 피드 하나하나에 담아 운영합니다.');
INSERT INTO `content_overrides` (`page`,`orig`,`new`) VALUES ('svc-mkt','광고는 넘기고, 콘텐츠엔 멈춥니다. 경쟁도가 강한 키워드는 최적화 기자단, 약한 키워드는 준최 기자단으로 — 광고가 아닌 콘텐츠로 상위노출되어 브랜드 신뢰를 높이고, 인천 지역 키워드까지 폭넓게 동시 노출합니다.','광고는 넘기고, 콘텐츠엔 멈춥니다.<br>경쟁도가 강한 키워드는 최적화 기자단, 약한 키워드는 준최 기자단으로<br>광고가 아닌 콘텐츠로 상위노출되어 브랜드 신뢰를 높이고,<br>인천 지역 키워드까지 폭넓게 동시 노출합니다.');
INSERT INTO `content_overrides` (`page`,`orig`,`new`) VALUES ('svc-mkt','이제는 검색도 인스타그램에서 시작됩니다. 인천 맛집·뷰티·서비스를 찾는 고객의 해시태그 검색에서 브랜드의 비주얼 콘텐츠를 추천 탭 상단에 노출시켜, 첫인상과 선택의 기준을 만들어 드립니다.','이제는 검색도 인스타그램에서 시작됩니다.<br>인천 맛집·뷰티·서비스를 찾는 고객의 해시태그 검색에서 브랜드의 비주얼 콘텐츠를<br>추천 탭 상단에 노출시켜, 첫인상과 선택의 기준을 만들어 드립니다.');
INSERT INTO `content_overrides` (`page`,`orig`,`new`) VALUES ('svc-mkt','네이버·구글 검색광고(SA)부터 정교한 타겟팅의 메타 광고(DA)까지, 마케팅 목표에 가장 적합한 매체와 소재를 전략적으로 분석합니다. 인천·수도권 지역 타겟팅으로 예산 낭비 없이 성과를 극대화합니다.','네이버·구글 검색광고(SA)부터 정교한 타겟팅의 메타 광고(DA)까지,<br>마케팅 목표에 가장 적합한 매체와 소재를 전략적으로 분석합니다.<br>인천·수도권 지역 타겟팅으로 예산 낭비 없이 성과를 극대화합니다.');
INSERT INTO `content_overrides` (`page`,`orig`,`new`) VALUES ('svc-mkt','브랜드를 기억시키는 가장 빠른 방법, 숏폼. 스튜디오·PD·기획자·마케터가 한 팀으로 기획부터 촬영·편집·알고리즘 확산까지 운영합니다. 인천·부천·시흥 매장은 현장 출장 촬영도 빠르게 잡아 드립니다.','브랜드를 기억시키는 가장 빠른 방법, 숏폼. 스튜디오·PD·기획자·마케터가<br>한 팀으로 기획부터 촬영·편집·알고리즘 확산까지 운영합니다.<br>인천·부천·시흥 매장은 현장 출장 촬영도 빠르게 잡아 드립니다.');
INSERT INTO `content_overrides` (`page`,`orig`,`new`) VALUES ('svc-mkt','브랜드 런칭, 신제품 출시 등 인천 기업의 PR 이슈를 주요 포털 뉴스 탭에 노출하는 마케팅입니다. 마케터와 전문 작가가 핵심 키워드를 전략적으로 배치한 보도자료를 제작해 신속하고 정확하게 송출합니다.','브랜드 런칭, 신제품 출시 등 인천 기업의 PR 이슈를 주요 포털 뉴스 탭에 노출하는 마케팅입니다. 마케터와 전문 작가가 핵심 키워드를 전략적으로 배치한<br>보도자료를 제작해 신속하고 정확하게 송출합니다.');
INSERT INTO `content_overrides` (`page`,`orig`,`new`) VALUES ('svc-mkt','마케팅 · 광고 세부 서비스','마케팅 · 광고 서비스');
INSERT INTO `seo_overrides` (`page`,`title`,`description`,`keywords`) VALUES ('index','인천 브로슈어 리플렛 팜플렛 카탈로그 카다로그 제작 디자인 I 퍼스트디자인 인천지사','인천·부천·서부수도권 기업·관공서·교육기관 전문\n브로슈어 리플렛 팜플렛 카탈로그 카다로그 제작 디자인, 퍼스트디자인 인천지사','인천 디자인, 카탈로그 제작, 브로슈어 제작, 리플렛 제작, 포스터 제작, 로고 디자인, 회사소개서 제작, 인천 인쇄');
INSERT INTO `seo_overrides` (`page`,`title`,`description`,`keywords`) VALUES ('about','회사소개 | 퍼스트디자인 인천지사','기업·관공서·교육기관과 12년, 이제 인천에서도. 카탈로그·브로슈어·리플렛·팜플렛 디자인 제작 전문 퍼스트디자인 인천지사','');
INSERT INTO `seo_overrides` (`page`,`title`,`description`,`keywords`) VALUES ('portfolio','포트폴리오 | 퍼스트디자인 인천지사','퍼스트디자인 인천지사 포트폴리오 — 기업·관공서·교육기관과 함께한 카탈로그·브로슈어·리플렛·팜플렛·로고·촬영 작업 450여 점을 확인하세요.','인천 디자인 포트폴리오, 카탈로그 브로슈어 리플렛 로고 제작 사례');
INSERT INTO `seo_overrides` (`page`,`title`,`description`,`keywords`) VALUES ('column','블로그 | 퍼스트디자인 인천지사','인천 기업을 위한 디자인·인쇄 인사이트\n카탈로그·브로슈어·팜플렛·리플렛 제작 전에 알아두면 좋은 팁과 인사이트를 퍼스트디자인 인천지사가 정리했습니다.','인천 디자인 블로그, 카탈로그 제작 팁, 인쇄 가이드');
INSERT INTO `seo_overrides` (`page`,`title`,`description`,`keywords`) VALUES ('contact','문의하기 | 퍼스트디자인 인천지사','인천 카탈로그·브로슈어·리플렛·로고 디자인 제작 문의. 무료 견적 상담, 인천 남동구 대면 미팅 가능. 전화 1600-9487, 평일 09:00–18:00.','인천 디자인 문의, 카탈로그 제작 견적, 인천 인쇄 상담');
INSERT INTO `seo_overrides` (`page`,`title`,`description`,`keywords`) VALUES ('svc-ppt','PPT · 제안서 디자인 제작 | 퍼스트디자인 인천지사','인천 PPT·제안서 디자인 전문 — 회사소개서, IR·입찰 제안서, 발표자료, 사내 템플릿까지. 원고 정리부터 디자인·마감 수정까지 한 팀이 진행합니다. 1600-9487','PPT 제작, 제안서 디자인, 회사소개 PPT, 인천 발표자료');
INSERT INTO `seo_overrides` (`page`,`title`,`description`,`keywords`) VALUES ('svc-brand','브랜딩 · 로고 디자인 제작 | 퍼스트디자인 인천지사','인천 로고 제작·브랜딩 전문 — CI·BI 디자인, 네이밍, 캐릭터, 창업 패키지까지. 업종·타깃 분석으로 오래 쓰는 브랜드를 설계합니다. 인천·부천·시흥 대면 상담, 1600-9487','로고 제작, 브랜딩, CI BI 디자인, 인천 로고 디자인, 네이밍');
INSERT INTO `seo_overrides` (`page`,`title`,`description`,`keywords`) VALUES ('svc-web','홈페이지 · 웹 디자인 제작 | 퍼스트디자인 인천지사','인천 홈페이지·웹 디자인 제작 — 반응형 홈페이지, 쇼핑몰, 상세페이지, 카드뉴스까지. 기획·디자인·오픈 후 관리까지 원스톱. 인천·부천·시흥 대면 상담, 1600-9487','홈페이지 제작, 웹 디자인, 반응형 홈페이지, 인천 웹사이트');
INSERT INTO `seo_overrides` (`page`,`title`,`description`,`keywords`) VALUES ('svc-studio','촬영 · 스튜디오 | 퍼스트디자인 인천지사','인천 제품 촬영·스튜디오 — 제품컷, 연출컷, 공간·현장 출장 촬영까지. 디자인을 아는 팀이 촬영해 카탈로그·상세페이지에 바로 쓰는 결과물을 만듭니다. 1600-9487','제품 촬영, 스튜디오 촬영, 인천 제품 사진, 상세페이지 촬영');
